from __future__ import annotations

import hashlib
import hmac
import secrets
import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, status
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from pydantic import BaseModel, Field

router = APIRouter(prefix="/auth", tags=["auth"])

_SECRET = secrets.token_bytes(32)
_USERS_BY_EMAIL: dict[str, dict[str, str]] = {}
_TOKENS: dict[str, dict[str, str]] = {}

bearer_scheme = HTTPBearer(auto_error=False, scheme_name="bearerAuth")


class RegisterRequest(BaseModel):
    email: str = Field(min_length=1)
    password: str = Field(min_length=1)
    name: str = Field(min_length=1)


class LoginRequest(BaseModel):
    email: str = Field(min_length=1)
    password: str = Field(min_length=1)


class UserResponse(BaseModel):
    id: str
    email: str
    name: str


class TokenResponse(BaseModel):
    access_token: str
    token_type: str


def _hash_password(password: str, salt: str) -> str:
    digest = hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt.encode("utf-8"), 10_000
    )
    return f"{salt}:{digest.hex()}"


def _verify_password(password: str, stored: str) -> bool:
    salt, _, expected = stored.partition(":")
    if not salt or not expected:
        return False
    candidate = _hash_password(password, salt)
    return hmac.compare_digest(candidate, stored)


async def get_authenticated_user(
    creds: Annotated[HTTPAuthorizationCredentials | None, Depends(bearer_scheme)],
) -> dict[str, str]:
    if creds is None or not creds.credentials:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Not authenticated")
    user = _TOKENS.get(creds.credentials)
    if user is None:
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid token")
    return user


@router.post(
    "/register",
    status_code=status.HTTP_201_CREATED,
    response_model=UserResponse,
    responses={409: {"description": "Email already registered"}},
    openapi_extra={"security": []},
)
async def register_user(payload: RegisterRequest) -> UserResponse:
    email_key = payload.email.strip().lower()
    if email_key in _USERS_BY_EMAIL:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="Email already exists")
    user_id = f"usr_{uuid.uuid4().hex[:12]}"
    salt = secrets.token_hex(8)
    _USERS_BY_EMAIL[email_key] = {
        "id": user_id,
        "email": email_key,
        "name": payload.name,
        "password_hash": _hash_password(payload.password, salt),
    }
    return UserResponse(id=user_id, email=email_key, name=payload.name)


@router.post(
    "/login",
    response_model=TokenResponse,
    responses={401: {"description": "Invalid credentials"}},
    openapi_extra={"security": []},
)
async def login_user(payload: LoginRequest) -> TokenResponse:
    email_key = payload.email.strip().lower()
    user = _USERS_BY_EMAIL.get(email_key)
    if user is None or not _verify_password(payload.password, user["password_hash"]):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Invalid credentials")
    sig = hmac.new(_SECRET, f"{user['id']}:{secrets.token_hex(8)}".encode("utf-8"), "sha256")
    token = sig.hexdigest()
    public_user = {"id": user["id"], "email": user["email"], "name": user["name"]}
    _TOKENS[token] = public_user
    return TokenResponse(access_token=token, token_type="bearer")


@router.get(
    "/me",
    response_model=UserResponse,
    responses={401: {"description": "Not authenticated"}},
)
async def get_me(
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> UserResponse:
    return UserResponse(id=user["id"], email=user["email"], name=user["name"])

from __future__ import annotations

import uuid
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from pydantic import BaseModel, Field, field_validator

from app.features.auth.router import get_authenticated_user

router = APIRouter(prefix="/bookmarks", tags=["bookmarks"])

_BOOKMARKS: dict[str, dict[str, Any]] = {}


def _validate_http_url(value: str) -> str:
    cleaned = value.strip()
    if not (cleaned.startswith("http://") or cleaned.startswith("https://")):
        raise ValueError("url must start with http:// or https://")
    return cleaned


class BookmarkCreate(BaseModel):
    url: str
    title: str = Field(min_length=1)
    description: str = ""
    tags: list[str] = Field(default_factory=list)

    @field_validator("url")
    @classmethod
    def _check_url(cls, v: str) -> str:
        return _validate_http_url(v)


class BookmarkUpdate(BaseModel):
    url: str | None = None
    title: str | None = Field(default=None, min_length=1)
    description: str | None = None
    tags: list[str] | None = None

    @field_validator("url")
    @classmethod
    def _check_url(cls, v: str | None) -> str | None:
        if v is None:
            return None
        return _validate_http_url(v)


class BookmarkResponse(BaseModel):
    id: str
    url: str
    title: str
    description: str
    tags: list[str]


class BookmarkPage(BaseModel):
    items: list[BookmarkResponse]
    total: int
    page: int
    size: int


def _to_response(record: dict[str, Any]) -> BookmarkResponse:
    return BookmarkResponse(
        id=str(record["id"]),
        url=str(record["url"]),
        title=str(record["title"]),
        description=str(record.get("description", "")),
        tags=[str(t) for t in record.get("tags", [])],
    )


@router.post(
    "",
    status_code=status.HTTP_201_CREATED,
    response_model=BookmarkResponse,
    responses={401: {"description": "Not authenticated"}},
)
async def create_bookmark(
    payload: BookmarkCreate,
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> BookmarkResponse:
    bm_id = f"bm_{uuid.uuid4().hex[:12]}"
    clean_tags = [t.strip() for t in payload.tags if t.strip()]
    record: dict[str, Any] = {
        "id": bm_id,
        "user_id": user["id"],
        "url": payload.url,
        "title": payload.title,
        "description": payload.description,
        "tags": clean_tags,
    }
    _BOOKMARKS[bm_id] = record
    return _to_response(record)


@router.get(
    "",
    response_model=BookmarkPage,
    responses={401: {"description": "Not authenticated"}},
)
async def list_bookmarks(
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
    q: str | None = None,
    tag: str | None = None,
    page: Annotated[int, Query(ge=1)] = 1,
    size: Annotated[int, Query(ge=1, le=100)] = 20,
) -> BookmarkPage:
    owned = [b for b in _BOOKMARKS.values() if b["user_id"] == user["id"]]
    if q:
        needle = q.strip().lower()
        owned = [
            b
            for b in owned
            if needle in str(b["title"]).lower()
            or needle in str(b["url"]).lower()
            or needle in str(b.get("description", "")).lower()
        ]
    if tag:
        owned = [b for b in owned if tag in b.get("tags", [])]

    total = len(owned)
    start = (page - 1) * size
    sliced = [_to_response(b) for b in owned[start : start + size]]
    return BookmarkPage(items=sliced, total=total, page=page, size=size)


@router.get(
    "/{bookmark_id}",
    response_model=BookmarkResponse,
    responses={401: {"description": "Not authenticated"}, 404: {"description": "Not found"}},
)
async def get_bookmark(
    bookmark_id: str,
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> BookmarkResponse:
    record = _BOOKMARKS.get(bookmark_id)
    if record is None or record["user_id"] != user["id"]:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bookmark not found")
    return _to_response(record)


@router.patch(
    "/{bookmark_id}",
    response_model=BookmarkResponse,
    responses={401: {"description": "Not authenticated"}, 404: {"description": "Not found"}},
)
async def update_bookmark(
    bookmark_id: str,
    payload: BookmarkUpdate,
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> BookmarkResponse:
    record = _BOOKMARKS.get(bookmark_id)
    if record is None or record["user_id"] != user["id"]:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bookmark not found")
    if payload.url is not None:
        record["url"] = payload.url
    if payload.title is not None:
        record["title"] = payload.title
    if payload.description is not None:
        record["description"] = payload.description
    if payload.tags is not None:
        record["tags"] = [t.strip() for t in payload.tags if t.strip()]
    return _to_response(record)


@router.delete(
    "/{bookmark_id}",
    status_code=status.HTTP_204_NO_CONTENT,
    responses={401: {"description": "Not authenticated"}, 404: {"description": "Not found"}},
)
async def delete_bookmark(
    bookmark_id: str,
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> Response:
    record = _BOOKMARKS.get(bookmark_id)
    if record is None or record["user_id"] != user["id"]:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Bookmark not found")
    del _BOOKMARKS[bookmark_id]
    return Response(status_code=status.HTTP_204_NO_CONTENT)

from __future__ import annotations

from collections import Counter
from typing import Annotated

from fastapi import APIRouter, Depends
from pydantic import BaseModel

from app.features.auth.router import get_authenticated_user
from app.features.bookmarks.router import _BOOKMARKS

router = APIRouter(prefix="/tags", tags=["tags"])


class TagCount(BaseModel):
    name: str
    count: int


class TagListResponse(BaseModel):
    items: list[TagCount]


@router.get(
    "",
    response_model=TagListResponse,
    responses={401: {"description": "Not authenticated"}},
)
async def list_tags(
    user: Annotated[dict[str, str], Depends(get_authenticated_user)],
) -> TagListResponse:
    counts: Counter[str] = Counter()
    for record in _BOOKMARKS.values():
        if record["user_id"] == user["id"]:
            for tag in record.get("tags", []):
                counts[str(tag)] += 1
    items = [TagCount(name=k, count=counts[k]) for k in sorted(counts)]
    return TagListResponse(items=items)
